#![no_std]
extern crate alloc;
use alloc::{alloc::Global, rc::Rc};
use core::alloc::Allocator;
use zstdoxide::{
    CompressionStrategy, Dictionary, Encoder, EncoderOptions, EndDirective, MatchSearchOptions,
    Result, SharedDictionary,
};

#[cfg(target_has_atomic = "ptr")]
compile_error!("This compile-only probe requires the no-pointer-atomics Rc branch.");

// This is code-generation evidence only, with no target execution or firmware
// memory-fit claim. Dictionary ownership remains distinct from encoder scratch.
pub fn borrowed_search<A: Allocator>(
    input: &[u8],
    allocator: &A,
    history: u32,
) -> Result<(MatchSearchOptions, usize, usize)> {
    let dictionary = Dictionary::raw_in(b"abcdefghi", allocator)?;
    let shared: Rc<Dictionary<&A>> = dictionary.into_shared();
    let alias: SharedDictionary<&A> = shared.clone();
    let mut encoder = Encoder::with_dictionary_in(
        EncoderOptions {
            strategy: CompressionStrategy::Lazy,
            window_log: 10,
            ..EncoderOptions::default()
        },
        alias,
        allocator,
    )?;
    let mut options = MatchSearchOptions::new();
    options.set_hash_log(10)?;
    options.set_chain_log(10)?;
    options.set_key_bytes(8)?;
    options.set_chain_visits(3)?;
    options.set_lazy_visits(5)?;
    options.set_history_bytes(history)?;
    encoder.set_search_options(options)?;
    let mut output = [0; 64];
    let _ = encoder.process(input, &mut output, EndDirective::Finish)?;
    let capacities = (
        encoder.search_retained_capacity(),
        encoder.retained_capacity(),
    );
    encoder.reset();
    encoder.set_prefix(shared)?;
    encoder.reset_with_options(EncoderOptions::default())?;
    encoder.reset_parameters()?;
    encoder.reset_all();
    Ok((encoder.search_options(), capacities.0, capacities.1))
}

// The owned variant instantiates fresh allocator clones and the same settings
// APIs without a dictionary. Returned scalars own no borrow into the context.
pub fn owned_search<A: Allocator + Clone>(
    input: &[u8],
    allocator: A,
    options: MatchSearchOptions,
) -> Result<(u8, u8, u8, u8, u8, u32, usize)> {
    let mut encoder = Encoder::new_in(allocator);
    encoder.set_search_options(options)?;
    let mut output = [0; 64];
    let _ = encoder.process(input, &mut output, EndDirective::Finish)?;
    let capacity = encoder.search_retained_capacity();
    encoder.reset_all();
    Ok((
        options.hash_log(),
        options.chain_log(),
        options.key_bytes(),
        options.chain_visits(),
        options.lazy_visits(),
        options.history_bytes(),
        capacity,
    ))
}

pub fn instantiate_owned(input: &[u8]) -> Result<usize> {
    Ok(owned_search(input, Global, MatchSearchOptions::default())?.6)
}

pub fn instantiate_borrowed(input: &[u8], history: u32) -> Result<usize> {
    Ok(borrowed_search(input, &Global, history)?.1)
}
